# /// script
# requires-python = ">=3.12"
# dependencies = ["python-telegram-bot>=21.0", "python-dotenv>=1.0.0", "aiohttp>=3.9,<4", "tzdata>=2024.1", "yt-dlp[default,deno]==2026.8.19", "py-tgcalls[telethon]==3.0.0", "Telethon==1.45.0"]
# ///
"""Karzon Bot: all application code, translations and assets in one file.

python main.py --install   Install dependencies.
python main.py --check     Validate the embedded application without connecting.
python main.py            Start one bot instance.
python main.py --export DIR  Export editable sources to an empty directory.

Secrets are read from environment variables or a local .env file.
User data is stored separately in DB_PATH (default: database/karzoni_bot.db).
"""
import argparse
import base64
import importlib.util
import io
import json
import os
from pathlib import Path
import runpy
import subprocess
import sys
import tempfile
import zipfile

DEPENDENCIES = ('python-telegram-bot>=21.0', 'python-dotenv>=1.0.0', 'aiohttp>=3.9,<4', 'tzdata>=2024.1', 'yt-dlp[default,deno]==2026.8.19', 'py-tgcalls[telethon]==3.0.0', 'Telethon==1.45.0')
PAYLOAD = """"""


def unpack(destination):
    destination = Path(destination).resolve()
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as archive:
        for item in archive.infolist():
            target = (destination / item.filename).resolve()
            if not target.is_relative_to(destination):
                raise RuntimeError("Invalid embedded path")
            content = archive.read(item)
            if target.suffix == ".py":
                compile(content, item.filename, "exec")
            elif target.suffix == ".json":
                json.loads(content)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(content)


def main():
    parser = argparse.ArgumentParser(description="Karzon Bot - single-file application")
    parser.add_argument("--install", action="store_true", help="Install Python dependencies and exit")
    parser.add_argument("--check", action="store_true", help="Validate all embedded files without starting the bot")
    parser.add_argument("--export", metavar="DIR", help="Export editable sources into an empty directory")
    parser.add_argument("--music-login", action="store_true", help="Create a private Telegram music session locally")
    args = parser.parse_args()
    if sum((args.install, args.check, bool(args.export), args.music_login)) > 1:
        parser.error("Choose only one operation")
    if args.install:
        return subprocess.call([sys.executable, "-m", "pip", "install", *DEPENDENCIES])
    if args.export:
        destination = Path(args.export).expanduser().resolve()
        if destination.exists() and (not destination.is_dir() or any(destination.iterdir())):
            parser.error("Export destination must be an empty directory")
        unpack(destination)
        print("Editable sources exported.")
        return 0
    if args.check:
        with tempfile.TemporaryDirectory(prefix="karzon-check-") as runtime:
            unpack(runtime)
        print("OK: application, Russian translations and assets verified.")
        return 0
    missing = [name for name in ("telegram", "dotenv", "aiohttp", "tzdata") if importlib.util.find_spec(name) is None]
    if missing:
        print("Missing dependencies. Run: python main.py --install", file=sys.stderr)
        return 1
    root = Path(__file__).resolve().parent
    from dotenv import load_dotenv
    load_dotenv(root / ".env")
    load_dotenv(root / ".env.music")
    os.environ.setdefault("DB_PATH", str(root / "database" / "karzoni_bot.db"))
    sys.dont_write_bytecode = True
    with tempfile.TemporaryDirectory(prefix="karzon-runtime-") as runtime:
        unpack(runtime)
        sys.path.insert(0, runtime)
        if args.music_login:
            os.environ["KARZON_MUSIC_ENV"] = str(root / ".env.music")
            runpy.run_path(str(Path(runtime) / "music_login.py"), run_name="__main__")
        else:
            runpy.run_path(str(Path(runtime) / "main.py"), run_name="__main__")
    return 0


if __name__ == "__main__":
    sys.exit(main())
